NAME = 'ACV: A Conservative Version'
BOOK = 'Ezra'

CHAPTERS = {
    1: {
        1: 'V prvem letu Cira, kralja v Perziji, je Gospod, da bi se dopolnila beseda Gospodova, govorjena po ustih Jeremijevih, obudil duha Cira, kralja v Perziji, da je dal razglasiti po vsej kraljevini svoji, pa tudi pismeno naznaniti:',
        2: 'Tako pravi Cir, kralj Perzije: Vsa kraljestva zemlje mi je dal Gospod, Bog nebes, in mi je naročil, naj mu zgradim hišo v Jeruzalemu, ki je na Judovem.',
        3: 'Kdor je med vami iz vsega ljudstva njegovega, s tem bodi njegov Bog, in pojdi gori v Jeruzalem na Judovem in zidaj hišo Gospoda, Boga Izraelovega (on je Bog!), ki je v Jeruzalemu.',
        4: 'Vsakemu torej, ki je preostal na kateremkoli mestu, kjer biva kot tujec, naj mu pomagajo ljudje tega kraja s srebrom in zlatom, z blagom in z živino, razen tega, kar dobrovoljno darujejo za hišo Božjo, ki je v Jeruzalemu!',
        5: 'Nato se vzdignejo prvaki očetovin Judovih in Benjaminovih ter duhovniki in leviti, vsi, katerih duha je bil obudil Bog, da pojdejo gori gradit hišo Gospodovo, ki je v Jeruzalemu.',
        6: 'In vsi, ki so bili okoli njih, so jim podpirali roke s srebrnimi potrebščinami, z zlatom, z blagom, z živino in z dragotinami, razen vsega, kar so dali dobrovoljno.',
        7: 'Cir pa je velel prinesti ven posode hiše Gospodove, ki jih je bil Nebukadnezar pripeljal iz Jeruzalema ter jih je dejal v svojega boga hišo;',
        8: 'te je dal Cir, kralj Perzije, prinesti po Mitredatu, zakladničarju, in jih je odštel Sesbazarju, vojvodu Judovemu.',
        9: 'In to je njih število: trideset zlatih skled, tisoč srebrnih skled, devetindvajset nožev;',
        10: 'trideset zlatih čaš, srebrnih čaš druge vrste štiristo in deset in drugih posod tisoč.',
        11: 'Vseh zlatih in srebrnih posod je bilo pet tisoč in štiristo. Te vse je prinesel Sesbazar s seboj, ko so šli iz ujetništva v Babilonu gori v Jeruzalem.',
    },
    2: {
        1: 'Ti pa so sinovi pokrajine Judove, kateri so šli iz sužnosti tistih, ki so bili odpeljani v ujetništvo, ki jih je bil Nebukadnezar, kralj babilonski, ujete odpeljal v Babilon in ki so se zopet vrnili v Jeruzalem in na Judovo, vsak v svoje mesto;',
        2: 'ki so prišli z Zerubabelom, Jesuom, Nehemijem, Serajem, Reelajem, Mardohejem, Bilsanom, Misparjem, Bigvajem, Rehumom, Baanom. Število mož iz ljudstva Izraelovega:',
        3: 'Sinovi Paroševi: dva tisoč sto dvainsedemdeset.',
        4: 'Sinovi Sefatijevi: tristo dvainsedemdeset.',
        5: 'Sinovi Arahovi: sedemsto petinsedemdeset.',
        6: 'Sinovi Pahat-moabovi, iz otrok Jesua in Joaba: dva tisoč osemsto in dvanajst.',
        7: 'Sinovi Elamovi: tisoč dvesto štiriinpetdeset.',
        8: 'Sinovi Zatujevi: devetsto petinštirideset.',
        9: 'Sinovi Zakajevi: sedemsto in šestdeset.',
        10: 'Sinovi Banijevi: šeststo dvainštirideset.',
        11: 'Sinovi Bebajevi: šeststo triindvajset.',
        12: 'Sinovi Azgadovi: tisoč dvesto in dvaindvajset.',
        13: 'Sinovi Adonikamovi: šeststo šestinšestdeset.',
        14: 'Sinovi Bigvajevi: dva tisoč šestinpetdeset.',
        15: 'Sinovi Adinovi: štiristo štiriinpetdeset.',
        16: 'sinovi Aterjevi, od Hezekija: osemindevetdeset.',
        17: 'Sinovi Bezajevi: tristo in triindvajset.',
        18: 'Sinovi Jorovi: sto in dvanajst.',
        19: 'Sinovi Hasumovi: dvesto triindvajset.',
        20: 'Sinovi Gibarjevi: petindevetdeset.',
        21: 'Sinovi Betlehemovi: sto triindvajset.',
        22: 'Možje iz Netofe: šestinpetdeset.',
        23: 'Možje iz Anatota: sto osemindvajset.',
        24: 'Sinovi iz Azmaveta: dvainštirideset.',
        25: 'Sinovi iz Kirjat-arima, Kefire in Beerota, sedemsto triinštirideset.',
        26: 'Sinovi iz Rame in Gebe: Šeststo in edenindvajset.',
        27: 'Možje iz Mikmasa: sto dvaindvajset.',
        28: 'Možje iz Betela in Aja: dvesto triindvajset.',
        29: 'Sinovi Nebovi: dvainpetdeset.',
        30: 'Sinovi Magbiševi: sto šestinpetdeset.',
        31: 'Sinovi drugega Elama: tisoč dvesto štiriinpetdeset.',
        32: 'Sinovi Harimovi: tristo in dvajset.',
        33: 'Sinovi Loda, Hadida in Ona: sedemsto petindvajset.',
        34: 'Možje iz Jeriha: tristo petinštirideset.',
        35: 'Sinovi od Senaa: tri tisoč šeststo in trideset.',
        36: 'Duhovniki: Sinovi Jedaja, iz hiše Jesuove: devetsto triinsedemdeset.',
        37: 'Sinovi Imerjevi: tisoč dvainpetdeset.',
        38: 'Sinovi Pashurja: tisoč dvesto sedeminštirideset.',
        39: 'Sinovi Harima: tisoč in sedemnajst.',
        40: 'Leviti: Sinovi Jesua in Kadmiela, od sinov Hodavijevih: štiriinsedemdeset.',
        41: 'Pevci, sinovi Asafovi: sto osemindvajset.',
        42: 'Sinovi vratarjev: sinovi Saluma, sinovi Aterja, sinovi Talmona, sinovi Akuba, sinovi Hatita, sinovi Sobaja, skupaj sto devetintrideset.',
        43: 'Netinimci: Sinovi Zihovi, sinovi Hasufovi, sinovi Tabaotovi,',
        44: 'sinovi Kerosovi, sinovi Siahovi, sinovi Padonovi,',
        45: 'sinovi Lebanovi, sinovi Hagabajevi, sinovi Akubovi,',
        46: 'sinovi Hagabovi, sinovi Samlajevi, sinovi Hananovi,',
        47: 'sinovi Gidelovi, sinovi Gaharjevi, sinovi Reajevi,',
        48: 'sinovi Rezinovi, sinovi Nekodovi, sinovi Gazamovi,',
        49: 'sinovi Uzovi, sinovi Paseahovi, sinovi Besajevi,',
        50: 'sinovi Asnovi, sinovi Meunimov, sinovi Nefisimov,',
        51: 'sinovi Bakbukovi, sinovi Hakufovi, sinovi Harhurjevi,',
        52: 'sinovi Bazlutovi, sinovi Mehidovi, sinovi Harsajevi,',
        53: 'sinovi Barkosovi, sinovi Siserjevi, sinovi Tamahovi,',
        54: 'sinovi Neziahovi, sinovi Hatifovi.',
        55: 'Sinovi hlapcev Salomonovih: sinovi Sotajevi, sinovi Soferetovi, sinovi Perudovi,',
        56: 'sinovi Jaalovi, sinovi Darkonovi, sinovi Gidelovi,',
        57: 'sinovi Sefatijevi, sinovi Hatilovi, sinovi Pohereta iz Hazebaima, sinovi Amijevi.',
        58: 'Vseh Netinimcev in sinov hlapcev Salomonovih je bilo tristo dvaindevetdeset.',
        59: 'In ti so tudi šli gori iz Telmelaha, Telharsa, Keruba, Adana, Imerja, ali niso mogli izkazati svojih očetov hiše in svoje rodovine, da so iz Izraela:',
        60: 'sinovi Delajevi, sinovi Tobijevi, sinovi Nekodovi: šeststo dvainpetdeset.',
        61: 'In iz sinov duhovnikov: sinovi Habajevi, sinovi Hakozovi, sinovi Barzilaja, ki si je vzel ženo iz hčera Barzilaja Gileadčana in je bil po njih imenu imenovan.',
        62: 'Ti so iskali svojega rodu imenik, pa ga niso našli, zato so jih šteli za nečiste za duhovništvo.',
        63: 'In Tirsata jim je rekel, da naj ne jedo od najsvetejšega, dokler ne vstane duhovnik z Urimom in Tumimom.',
        64: 'Ves zbor je štel dvainštirideset tisoč tristo in šestdeset,',
        65: 'brez njih hlapcev in dekel, katerih je bilo sedem tisoč tristo sedemintrideset; imeli so tudi dvesto pevcev in pevk.',
        66: 'Njih konj je bilo sedemsto šestintrideset, njih mezgov dvesto in petinštirideset,',
        67: 'njih velblodov štiristo in petintrideset, oslov pa šest tisoč sedemsto in dvajset.',
        68: 'In nekateri poglavarji očetovin, ko so prišli k hiši Gospodovi, ki je v Jeruzalemu, so dali prostovoljnih daril za zgradbo hiše na mestu njenem;',
        69: 'po premožnosti svoji so dali v stavbni zaklad: edeninšestdeset tisoč darikov in pet tisoč min srebra in sto duhovniških oblačil.',
        70: 'In nastanili so se duhovniki in leviti in kar jih je bilo iz ljudstva in pevci in vratarji in Netinimci v mestih svojih in ves Izrael po mestih svojih.',
    },
    3: {
        1: 'In ko se je približal sedmi mesec in so že bili sinovi Izraelovi v svojih mestih, tedaj se zbere ljudstvo kakor en mož v Jeruzalemu.',
        2: 'Tedaj vstane Jesua, sin Jozadakov, in bratje njegovi, duhovniki, in Zerubabel, sin Sealtielov, in bratje njegovi, in zgrade oltar Boga Izraelovega, da se darujejo na njem žgalne daritve, kakor je pisano v postavi Mojzesa, moža Božjega.',
        3: 'In postavili so oltar na njegovi podstavi, kajti strah jih je bilo zaradi ljudstev sosednjih dežel; in darovali so na njem žgalne daritve Gospodu, žgalne daritve zjutraj in zvečer.',
        4: 'In praznovali so praznik šatorov, kakor je predpisano, in darovali žgalščine vsak dan po številu, soglasno s predpisom, kakor je bilo vsak dan obvezno.',
        5: 'In potem stalno žgalno daritev in daritve ob mlajih in ob vseh določenih praznikih Gospodovih, ki so bili posvečeni, in daritve vsakega, ki je Gospodu prinesel prostovoljno darilo.',
        6: 'Prvi dan sedmega meseca so začeli darovati žgalščine Gospodu, ko še ni bila položena podstava templju Gospodovemu.',
        7: 'In dali so denarja kamenosekom in tesarjem in živeža, pijače in olja tistim iz Sidona in iz Tira, da bi privažali cedrov les z Libanona na morje v Jafo, kakor jih je pooblastil Cir, kralj Perzije.',
        8: 'In v drugem letu po njih prihodu k hiši Božji v Jeruzalem, v drugem mesecu, so začeli Zerubabel, sin Sealtielov, in Jesua, sin Jozadakov, in ostali njih bratje, duhovniki in leviti, in vsi, ki so bili prišli iz ujetništva v Jeruzalem, in so postavili levite, dvajsetletne in starejše, da nadzorujejo delo hiše Gospodove.',
        9: 'Tedaj so stali, kakor en mož, Jesua s sinovi in z brati svojimi, Kadmiel in sinovi njegovi, sinovi Hodavijevi, da bi nadzorovali delavce pri hiši Božji, tudi sinovi Henadadovi s svojimi sinovi in brati, leviti, vred.',
        10: 'In ko so stavbarji pokladali podstavo templju Gospodovemu, so postavili duhovnike v njih oblačilih s trobentami in levite, sinove Asafove, s cimbali, da hvalijo Gospoda po naredbi Davida, kralja Izraelovega.',
        11: 'In odpevali so drugi drugim, hvaleč in zahvaljujoč Gospoda, ker je dobrotljiv, ker vekomaj traja milost njegova nad Izraelom. In vse ljudstvo je zagnalo radostno ukanje ob hvali Gospodovi, ker je položil temelj hiši Gospodovi.',
        12: 'A mnogi iz duhovnikov in levitov in poglavarjev očetovskih družin, stari možje, ki so bili videli prejšnjo hišo, so glasno jokali, ko se je pokladal temelj tej hiši pred njih očmi; mnogi so pa glasno vriskali od veselja;',
        13: 'tako da ljudstvo ni moglo razločiti veselega vriskanja od glasnega jokanja med ljudstvom, zakaj ljudstvo je vriskalo z močnim glasom, in glas se je daleč razlegal.',
    },
    4: {
        1: 'Ko so pa slišali nasprotniki Judovi in Benjaminovi, da grade sinovi ujetništva tempelj Gospodu, Bogu Izraelovemu,',
        2: 'pristopijo k Zerubabelu in k poglavarjem očetovin in jim reko: Naj zidamo z vami, kajti mi iščemo vašega Boga prav tako kot vi. Ali mu ne darujemo od časa Esar-hadona, kralja asirskega, ki nas je pripeljal sem gori?',
        3: 'Toda Zerubabel in Jesua in drugi poglavarji Izraelovih očetovin jim reko: Ne spodobi se vam, da z nami zidate hišo našemu Bogu, temuč mi sami hočemo zidati Gospodu, Bogu Izraelovemu, kakor nam je zapovedal kralj Cir, kralj Perzije!',
        4: 'Tedaj je ljudstvo dežele slabilo roke ljudstvu Judovemu ter jih s strašenjem motilo pri zidanju.',
        5: 'In najemali so svetnike zoper nje, da podkopljejo njih namero, vse dni Cira, kralja perzijskega, do kraljevanja Darija, kralja Perzije.',
        6: 'In ob vladanju Ahasvera, v začetku njegovega kraljevanja, so tožbo pisali zoper prebivalce na Judovem in v Jeruzalemu.',
        7: 'In v dnevih Artakserksa so pisali Bislam, Mitredat, Tabeel in drugi njegovi tovariši Artakserksu, kralju v Perziji. In pisava pisma je bila sirska in po sirsko se je bralo.',
        8: 'Rehum, deželni poglavar, in Simsaj, pisar, sta napisala pismo zoper Jeruzalem kralju Artakserksu takole:',
        9: '(Takrat so pisali Rehum, deželni poglavar, in Simsaj, pisar, in drugi njih tovariši, Dinaji, Afarsatkaji, Tarpelaji, Afarsaji, Arkovci, Babilonci, Susančani, Dehaji, Elamljani',
        10: 'in drugi tistih narodov, ki jih je veliki in presvetli Oznapar sem pripeljal in jih naselil v mestih Samarije in v ostali deželi na tej strani reke Evfrata, in tako dalje.)',
        11: 'To je prepis lista, ki so ga poslali Artakserksu kralju: Tvoji hlapci, možje tostran reke, in tako dalje.',
        12: 'Znano bodi kralju, da so Judje, ki so prišli gori od tebe, dospeli k nam v Jeruzalem; oni zidajo tisto uporno in hudobno mesto in izpolnjujejo obzidje ter popravljajo podstave.',
        13: 'Znano torej bodi kralju: ako bode to mesto dozidano in obzidje dovršeno, ne bodo dajali davkov, ne užitnine, ne cestnine, in to naposled oškoduje kralja.',
        14: 'Zatorej, ker jemo sol palače, ne smemo gledati škode kraljeve, pa pošiljamo h kralju in mu to poročamo,',
        15: 'naj se poišče v spominski knjigi očetov tvojih; in najdeš v knjigi spominov in izveš, da je to mesto uporno mesto in škodljivo kraljem in deželam ter da so se v njem snovale vstaje od starodavna; zategadelj je tudi bilo to mesto porušeno.',
        16: 'Zagotavljamo kralja, ako se to mesto dozida in obzidje dovrši, da ne boš vsled tega imel nobene posesti tostran reke. –',
        17: 'Nato pošlje kralj odgovor Rehumu, deželnemu poglavarju, in Simsaju, pisarju, in drugim njih tovarišem, ki prebivajo v Samariji in drugih krajih tostran reke: Mir! in tako dalje.',
        18: 'List, ki ste ga nam poslali, se je umljivo bral pred menoj.',
        19: 'In velel sem, naj se preišče, in našlo se je, da je tisto mesto rovalo zoper kralje od starodavna ter da so upore in vstaje snovali v njem.',
        20: 'In bili so tudi mogočni kralji v Jeruzalemu, ki so gospodovali vsej deželi onostran reke, ki jim je bilo dajati davke, užitnino in cestnino.',
        21: 'Izdajte torej povelje, da se zabrani tistim možem in da se to mesto ne bo zidalo, dokler ne izide moje povelje.',
        22: 'In glejte, da ne storite v tem pomote; čemu naj raste škoda, da bodo kralji na izgubi?',
        23: 'ko se je opis lista kralja Artakserksa prečital pred Rehumom in Simsajem, pisarjem, in pred njih tovariši, so hitro šli gori v Jeruzalem k Judom in so jim branili z močno pestjo.',
        24: 'Takrat je nehalo delo pri hiši Božji, ki je v Jeruzalemu, in bilo je ustavljeno do drugega leta vlade Darija, kralja Perzije.',
    },
    5: {
        1: 'Prorokovala sta pa Hagaj, prorok, in Zaharija, sin Idov, proroka, Judom, ki so bili na Judovem in v Jeruzalemu; v imenu Boga Izraelovega sta jim prorokovala.',
        2: 'Tedaj vstane Zerubabel, sin Sealtielov, in Jesua, sin Jozadakov, ter začneta zidati hišo Božjo, ki je v Jeruzalemu, in ž njima proroka Božja, ki sta ju podpirala.',
        3: 'V istem času pride k njim Tatenaj, deželski oblastnik tostran reke, in Setar-bozenaj in njiju tovariši ter jim reko takole: Kdo vam je ukazal zidati to hišo in dokončati to obzidje?',
        4: 'Nato smo jim povedali, katera so imena mož, ki so se lotili zidanja.',
        5: 'A oko njih Boga je bilo obrnjeno v starejšine Judov, da se jim ni branilo, dokler se ni stvar sporočila Dariju in se je potem odposlal pismen odgovor o tem.',
        6: 'To pa je opis lista, ki so ga poslali Tatenaj, deželski oblastnik tostran reke, in Setar-bozenaj in njegovi tovariši Afarsakaji, ki so bili tostran reke, kralju Dariju.',
        7: 'Poslali so mu poročilo, v katerem je bilo pisano takole: Kralju Dariju ves mir!',
        8: 'Znano bodi kralju, da smo šli v pokrajino Judovo, k hiši velikega Boga, ki jo grade z velikimi kameni in ji brune pokladajo v stene, in delo to, ker so marljivi, je uspešno v njih rokah.',
        9: 'Tedaj smo vprašali tiste starejšine in jim rekli takole: Kdo vam je ukazal zidati to hišo in dokončati to obzidje?',
        10: 'Vprašali smo jih tudi za njih imena, da tebi oznanimo, da bi zapisali imena mož, ki jim načelujejo.',
        11: 'Oni pa so nam dali tak odgovor, rekoč: Mi smo hlapci Boga nebes in zemlje ter zidamo hišo, ki je bila prej zgrajena pred mnogimi leti, ki jo je velik kralj Izraelov zidal in dokončal.',
        12: 'A potem, ko so očetje naši dražili v jezo Boga nebes, jih je dal v roko Nebukadnezarja, kralja babilonskega, Kaldejca, ki je podrl to hišo in ljudstvo odpeljal v Babilon.',
        13: 'Toda v prvem letu Cira, kralja babilonskega, je kralj Cir izdal povelje, da naj se zida ta hiša Božja.',
        14: 'Tudi zlate in srebrne posode hiše Božje, ki jih je bil vzel Nebukadnezar iz templja v Jeruzalemu in jih prinesel v tempelj v Babilonu, je vzel kralj Cir iz templja v Babilonu in jih izročil tistemu, po imenu Sesbazarju, ki ga je postavil za oblastnika v deželi,',
        15: 'in mu je velel: Vzemi te posode, pojdi, deni jih v tempelj, ki je v Jeruzalemu, in naj se hiša Božja gradi na mestu njenem.',
        16: 'Takrat je prišel tisti Sesbazar in je položil podstave hiši Božji, ki je v Jeruzalemu, in od tega časa do sedaj jo zidajo, in ni še dokončana. –',
        17: 'Sedaj torej, ako se vzvidi kralju, naj poiščejo v kraljevi hiši, v zakladnici, ki je tam v Babilonu, če je tako, da je izdal kralj Cir povelje zidati to hišo Božjo v Jeruzalemu, in naj nam kralj sporoči svojo voljo za to stvar.',
    },
    6: {
        1: 'Nato ukaže kralj Darij, naj poiščejo v pismarnici v hiši, kjer so bili zloženi zakladi v Babilonu.',
        2: 'In našli so v Ahmeti, na gradu, ki je v pokrajini Medijski, zavitek, in v njem je bilo takole pisano v spomin:',
        3: 'V prvem letu kralja Cira, je izdal kralj Cir povelje: Zastran hiše Božje v Jeruzalemu: Ta hiša naj se zida kot kraj, kjer se darujejo daritve. Njene podstave naj se trdno postavijo; višava njena bodi šestdeset komolcev, širjava njena šestdeset komolcev;',
        4: 'tri lege imej štirivoglatih kamenov in eno lego iz novega lesa. In stroški naj se plačajo iz kraljeve hiše.',
        5: 'Tudi zlate in srebrne posode hiše Božje, ki jih je vzel Nebukadnezar iz templja v Jeruzalemu ter prinesel v Babilon, naj se povrnejo in zopet prineso na svoje mesto v tempelj v Jeruzalemu, in naj jih zlože v hiši Božji. –',
        6: 'Sedaj torej, Tatenaj, deželni oblastnik za reko, Setar-bozenaj in vajini tovariši Afarsakaji, ki ste za reko, umeknite se daleč od njih!',
        7: 'Pustite jim delati pri tej hiši Božji; naj poglavar Judov in starejšine Judov grade to hišo Božjo na mestu njenem.',
        8: 'Vrhutega sem izdal povelje, kako naj pomagate tistim starejšinam Judov pri stavbi te hiše Božje, namreč, da se iz kraljevega imetja, iz davkov onostran reke, plačujejo stroški z vso natančnostjo tem možem, da jim ne bode ovire.',
        9: 'In kar potrebujejo, telet, ovnov in jagnjet v žgalne daritve Bogu nebes, pšenice, soli, vina in olja, po zahtevi duhovnikov v Jeruzalemu, naj se jim daje dan za dnevom neprestano,',
        10: 'da morejo darovati daritve v prijetno dišavo Bogu nebes in da molijo za kraljevo in za sinov njegovih življenje.',
        11: 'Tudi sem izdal povelje: Vsakemu, ki premeni ta ukaz, naj vzamejo gredo iz hiše njegove in jo pokonci postavijo ter ga na njej obesijo, njegova hiša pa bodi v kup gnoja zavoljo tega.',
        12: 'A Bog, ki je storil, da bi ondi prebivalo ime njegovo, razdeni vse kralje in ljudstva, ki bodo iztegnili roko svojo, da premene ta ukaz, da se poruši ta hiša Božja v Jeruzalemu. Jaz, Darij, sem izdal povelje; naj se natančno izvrši!',
        13: 'Tedaj so storili Tatenej, deželni oblastnik za reko, Setar-bozenaj in njiju tovariši natančno tako, za kar je bil kralj Darij sporočil.',
        14: 'In starejšine Judovi so zidali in uspevalo jim je delo po prorokovanju Hagaja, proroka, in Zaharija, sinu Idovega. Tako so zidali in dokončali po zapovedi Boga Izraelovega in po povelju Cira in Darija in Artakserksa, kraljev v Perziji.',
        15: 'In ta hiša je bila dokončana tretji dan meseca Adarja, ko je bilo šesto leto vladanja kralja Darija.',
        16: 'In sinovi Izraelovi, duhovniki, leviti in drugi sinovi ujetništva so praznovali posvečevanje te hiše Božje z veseljem.',
        17: 'In prinesli so ob posvečevanju te hiše Božje sto juncev, dvesto ovnov, štiristo jagnjet; in v daritev za greh za vsega Izraela dvanajst kozlov, po številu rodov Izraelovih.',
        18: 'In postavili so duhovnike po njih vrstah in levite po njih oddelkih v službo Bogu, ki je v Jeruzalemu, kakor je pisano v knjigi Mojzesovi.',
        19: 'In sinovi ujetništva so praznovali pasho štirinajsti dan prvega meseca.',
        20: 'Zakaj duhovniki in leviti so se očistili kakor en mož; bili so vsi čisti. In zaklali so pasho za vse sinove ujetništva in za brate svoje, duhovnike, in zase.',
        21: 'In sinovi Izraelovi, ki so se bili vrnili iz ujetništva, in vsi, ki so se ločili od nečistote poganov v deželi in k njim pristopili, da bi iskali Gospoda, Boga Izraelovega, so jedli',
        22: 'in so praznovali praznik opresnikov sedem dni z veseljem; zakaj Gospod jim je bil dal veselje in jim je naklonil srce kralja asirskega, da bi jim okrepčal roke na delu pri hiši Boga, Boga Izraelovega.',
    },
    7: {
        1: 'A po teh zgodbah, ob vladanju Artakserksa, kralja v Perziji, je šel Ezra, sin Seraja, sinu Azarija, sinu Hilkija,',
        2: 'sinu Saluma, sinu Zadoka, sinu Ahituba,',
        3: 'sinu Amarija, sinu Azarija, sinu Merajota,',
        4: 'sinu Zerahija, sinu Uzija, sinu Bukija,',
        5: 'sinu Abisua, sinu Pinehasa, sinu Eleazarja, sinu Arona, prvega duhovnika –',
        6: 'ta Ezra je šel gori iz Babilona. Ta je bil Pismouk, izurjen v zakonu Mojzesovem, ki ga je bil dal Gospod, Bog Izraelov. In ker je bila roka Gospoda, Boga njegovega, nad njim, mu je dal kralj vse, kar je prosil.',
        7: 'In ž njim je šlo nekaj sinov Izraelovih in duhovnikov in levitov in pevcev in vratarjev in Netinimcev gori v Jeruzalem, v sedmem letu kralja Artakserksa.',
        8: 'In dospel je v Jeruzalem v petem mesecu, ko je bilo sedmo leto kraljevo.',
        9: 'Zakaj prvi dan prvega meseca je bil določen odhod iz Babilona, prvi dan petega meseca pa je dospel v Jeruzalem, kjer je bila dobrotljiva roka Boga njegovega nad njim.',
        10: 'Zakaj Ezra je pripravil srce svoje, da bo preiskoval zakon Gospodov in ga izpolnjeval ter da bo učil v Izraelu postave in sodbe.',
        11: 'To pa je prepis lista, ki ga je dal kralj Artakserks duhovniku in pismouku Ezru, pismouku v besedah zapovedi Gospodovih in njegovih postav za Izraela.',
        12: 'Artakserks, kralj kraljev, Ezru duhovniku, popolnemu pismouku zakona Boga nebes, in tako dalje.',
        13: 'Izdajem ukaz, da naj pojdejo s teboj vsi od ljudstva Izraelovega in njih duhovnikov in levitov v državi moji, ki hočejo rade volje iti v Jeruzalem.',
        14: 'Ker si poslan od kralja in od njegovih sedmih svetovalcev, da napraviš preiskavo o Judi in Jeruzalemu na podlagi zakona Boga svojega, ki je v roki tvoji,',
        15: 'in da odneseš tja srebro in zlato, ki so ga kralj in svetniki njegovi radovoljno darovali Bogu Izraelovemu, čigar prebivališče je v Jeruzalemu,',
        16: 'in vse srebro in zlato, ki ga dobiš v vsej pokrajini Babilonski, s tem vred, kar bo ljudstvo in duhovništvo prostovoljno darovalo za hišo Boga svojega, ki je v Jeruzalemu:',
        17: 'zato nakupi z vso marljivostjo s temle denarjem govedi, ovnov, jagnjet in njim pristojnih jedilnih in pitnih daril ter jih daruj na oltarju v hiši Boga vašega, ki je v Jeruzalemu.',
        18: 'In kar se tebi in bratom tvojim vzvidi storiti z ostalim srebrom in zlatom, storíte po volji Boga svojega!',
        19: 'In posode, ki so ti dane za službo v hiši Boga tvojega, oddaj pošteno pred Bogom v Jeruzalemu.',
        20: 'In karkoli bo še potrebno za hišo Boga tvojega, kar se ti naključi izdati, daj iz kraljeve zakladnice.',
        21: 'In jaz, kralj Artakserks, ukazujem vsem zakladnikom, ki so za reko, storite z vso marljivostjo, karkoli vas bo prosil Ezra duhovnik, pismouk v zakonu Boga nebes;',
        22: 'dajte do sto talentov srebra in do sto meric pšenice in do sto batov vina in sto batov olja in soli brez mere.',
        23: 'Karkoli je zapovedano po Bogu nebes, naj se natančno stori za hišo Boga nebes, kajti čemu naj pride srd božji nad državo kraljevo in njegovih sinov?',
        24: 'Tudi se vam naznanja, da nimate oblasti, nakladati davke, užitnino in cestnino kateremukoli iz duhovnikov, levitov, pevcev, vratarjev, Netinimcev in služabnikov te hiše Božje.',
        25: 'Ti pa, Ezra, po modrosti tvojega Boga, katera je v tvoji roki, postavi za sodnike in pravdnike, ki naj sodijo vse ljudstvo onostran reke, vse take, ki poznajo tvojega Boga postave. In kdor jih ne pozna, tega naučite.',
        26: 'In kdorkoli ne bo izpolnjeval postave Boga tvojega in postave kraljeve, nad tem naj se izvrši sodba z vso strogostjo, bodisi na smrt ali v prognanstvo ali v zaplenjenje imetja ali v ječo.',
        27: 'Hvaljen bodi Jehova, naših očetov Bog, ki je to dal kralju v srce, da se odiči hiša Gospodova, ki je v Jeruzalemu,',
        28: 'in ki mi je naklonil milost pred kraljem in svetovalci njegovimi in pred vsemi kraljevimi močnimi vojvodami! In tako sem se ohrabril po roki Gospoda, Boga svojege, ki je bila nad menoj, in izbral sem prvake Izraelove, da bi šli gori z menoj.',
    },
    8: {
        1: 'Ti pa so poglavarji očetovin in to je rodopis tistih, ki so šli z menoj gori iz Babilona ob vladanju kralja Artakserksa.',
        2: 'Od sinov Pinehasovih: Gersom; od sinov Itamarjevih: Daniel; od sinov Davidovih: Hatuš.',
        3: 'Od sinov Sekanijevih, od sinov Paroševih: Zeharija, in ž njim je bilo štetih po rodopisu stoinpetdeset moških.',
        4: 'Od sinov Pahat-moaba: Eljoenaj, sin Zerahijev, in ž njim dvesto moških.',
        5: 'Od sinov Sekanijevih: sin Jahazielov in ž njim tristo moških.',
        6: 'Od sinov Adinovih: Ebed, sin Jonatanov, in ž njim petdeset moških.',
        7: 'Od sinov Elamovih pa: Jesaja, sin Atalijev, in ž njim sedemdeset moških.',
        8: 'Od sinov Sefatijevih: Zebadija, sin Mihaelov, in ž njim osemdeset moških.',
        9: 'Od sinov Joabovih: Obadija, sin Jehielov, in ž njim dvesto in osemnajst moških.',
        10: 'Od sinov Selomitovih: sin Josifijev in ž njim sto in šestdeset moških.',
        11: 'Od sinov Bebajevih: Zeharija, sin Bebajev, in ž njim osemindvajset moških.',
        12: 'Od sinov Azgadovih: Johanan, sin Hakatanov, in ž njim sto in deset moških.',
        13: 'Od sinov Adonikamovih, ki so bili zadnji, in njih imena so: Elifelet, Jegiel in Semaja in ž njimi šestdeset moških.',
        14: 'In od sinov Bigvajevih: Utaj in Zabud in ž njimi sedemdeset moških.',
        15: 'In zbral sem jih ob reki, ki teče v Ahavo, in tam smo taborili tri dni. In ko sem razgledoval ljudstvo in duhovnike, nisem ondi našel nikogar iz sinov Levijevih.',
        16: 'Tedaj pošljem po Eliezerja, Ariela, Semaja, Elnatana, Jariba, Elnatana, Natana, Zeharija in Mesulama, prvake, tudi po Jojariba in Elnatana, zvedenca.',
        17: 'Tem dam sporočilo za Ida, prvaka v kraju Kasifiji, in jim velim, kaj jim je govoriti z Idom in z brati njegovimi, Netinimci, v kraju Kasifiji, da bi nam privedli strežaje za hišo našega Boga.',
        18: 'In privedli so nam, ker je bila dobrotljiva roka Boga našega nad nami, razsodnega moža iz sinov Mahlija, sinu Levija, sinu Izraelovega, in Serebija ž njegovimi sinovi in brati, osemnajst,',
        19: 'in Hasabija in ž njim Jesaja iz sinov Merarijevih, brate njegove in njih sinove, dvajset,',
        20: 'od Netinimcev pa, ki jih je bil določil David in poglavarji, da bi stregli levitom, dvesto in dvajset Netinimcev; vsi iz njih so bili imenovani z imenom.',
        21: 'Nato sem oklical post ondi, pri reki Ahavi, da bi se ponižali pred Bogom svojim, da izprosimo od njega ravno pot za sebe in za otročiče svoje in za vse blago svoje.',
        22: 'Sramoval sem se namreč prositi kralja čete vojakov in konjikov, da bi nam pomagali zoper sovražnike na poti; kajti dejali smo bili kralju: Roka Boga našega je nad vsemi, ki ga iščejo, v dobro, a moč in jeza njegova je zoper vse, ki ga zapuščajo.',
        23: 'Postili smo se torej in Boga svojega prosili tega, in dal se nam je izprositi.',
        24: 'Nato sem odločil dvanajstero poglavarjev duhovnikov, Serebija in Hasabija in deset njiju bratov ž njima;',
        25: 'in odtehtal sem jim srebro in zlato in posode, dar povzdignjenja za hišo Boga našega, ki so ga bili darovali kralj in svetovalci in vojvode njegovi in vsi Izraelci, kar jih je bilo ondi.',
        26: 'Odtehtal sem, pravim, njim v roko šesto in petdeset talentov srebra in srebrnih posod za sto talentov, zlata pa sto talentov,',
        27: 'in dvajset zlatih čaš, vrednih tisoč darikov, in dve zlatožarni bronasti posodi, dragi ko zlato.',
        28: 'In sem jim velel: Vi ste sveti Gospodu, in te posode so svete, in srebro in zlato je dobrovoljen dar Gospodu, vaših očetu Bogu.',
        29: 'Bodite bedljivi in jih čuvajte, dokler jih ne stehtate pred poglavarji duhovnikov in levitov in poglavarji očetovin Izraelovih v Jeruzalemu, v hramih hiše Gospodove!',
        30: 'Vzeli so torej duhovniki in leviti stehtano srebro in zlato in posode, da jih doneso v Jeruzalem, v hišo Boga našega.',
        31: 'Potem smo odrinili od reke Ahave, dvanajsti dan prvega meseca, da potujemo v Jeruzalem; in roka Boga našega je bila nad nami, in otel nas je iz roke sovražnikov in opotnih zasednikov.',
        32: 'In dospeli smo v Jeruzalem in ondi ostali tri dni.',
        33: 'In četrti dan so srebro in zlato in posode stehtali v hiši Boga našega v roke Meremotu, sinu Urija duhovnika, in ž njim je bil Eleazar, sin Pinehasov, ž njima pa Jozabad, sin Jesuov, in Noadija, sin Binuja, levita;',
        34: 'vse po številu in po teži, in vsa teža je bila tisti čas zapisana.',
        35: 'Sinovi ujetništva, ki so se bili vrnili iz prognanstva, so darovali žgalne daritve Bogu Izraelovemu: dvanajst juncev za vsega Izraela, šestindevetdeset ovnov, sedeminsedemdeset jagnjet, dvanajst kozlov v daritev za greh, vse to v žgalščino Gospodu.',
        36: 'In izročili so kraljeve ukaze kraljevim namestnikom in deželskim oblastnikom tostran reke. Ti pa so podpirali ljudstvo in hišo Božjo.',
    },
    9: {
        1: 'Ko pa je to vse bilo opravljeno, pristopijo k meni poglavarji, govoreč: Ljudstvo Izraelovo in duhovniki in leviti se niso ločili od ljudstev dežele, delajoč po njih gnusobah, Kanaancev in Hetejcev, Ferizejcev, Jebusejcev, Amoncev, Moabcev, Egipčanov in Amorejcev.',
        2: 'Zakaj jemali so njih hčere zase in za svoje sinove in so se, sveto seme, zmešali z ljudmi teh dežel, in roka poglavarjev in načelnikov je bila prva v tej nezvestobi.',
        3: 'Ko sem to zaslišal, sem si raztrgal suknjo in plašč ter si pulil lase iz glave in brado in sedel potrt.',
        4: 'Tedaj se zbero k meni vsi, ki so trepetali ob besedah Boga Izraelovega zaradi nezvestobe tistih, ki so prišli iz ujetništva. Jaz pa sem sedel potrt do večerne daritve.',
        5: 'In ob večerni daritvi vstanem od svojega ponižanja z raztrgano suknjo in raztrganim plaščem, in padem na kolena in razprostrem roke proti Gospodu, Bogu svojemu,',
        6: 'in rečem: O Bog moj, sramujem se in bojim se povzdigniti obličje k tebi, moj Bog; zakaj krivice naše so nam zrasle nad glavo in krivda naša je dospela do neba!',
        7: 'Od očetov naših časa smo v veliki krivdi do tega dne, in zaradi krivic svojih smo bili izročeni mi, kralji naši in duhovniki naši rokam kraljev dežel, meču, ujetništvu, plenjenju in očitni sramoti, kakor je danes.',
        8: 'In sedaj nam je za kratek trenutek izkazal milost Gospod, naš Bog, da nam je pustil ostanek rešencev in dal, da smemo zabiti šatorov klin na svetem kraju njegovem, da bi nam Bog naš razsvetlil oči ter nas malo poživil v sužnosti naši.',
        9: 'Zakaj sužnji smo; vendar pa nas ni zapustil Bog naš v sužnosti naši, ampak nam je naklonil milost pred kralji Perzije, da bi nam pripravili oživitev, da postavimo hišo Božjo in popravimo razvaline njene, ter da bi nam dali zid v Judi in v Jeruzalemu.',
        10: 'In sedaj, Bog naš, kaj hočemo reči po vsem tem? Kajti zapustili smo tvoje zapovedi,',
        11: 'ki si jih zapovedal po hlapcih svojih, prorokih, rekši: Zemlja, v katero greste, da jo posedete, je nečista dežela vsled nečistosti poganskih ljudstev v deželi, vsled njih gnusob, s katerimi so jo napolnili od konca do kraja po svojem oskrunjevanju.',
        12: 'Sedaj torej ne dajajte hčer svojih njih sinovom, tudi ne jemljite njih hčer sinovom svojim, niti ne iščite njih miru in blaginje vekomaj, da bodete mogočni in boste uživali dobrino dežele ter jo zapustili v dediščino otrokom svojim vekomaj.',
        13: 'Po vsem tem pa, kar je prišlo nad nas za huda dela naša in za našo krivdo veliko (ker si ti, Bog naš, nas kaznoval manj, nego zaslužijo krivice naše, in si nam dal toliko rešencev tukaj),',
        14: 'bomo li zopet prelamljali zapovedi tvoje in svaštvo sklepali z ljudstvi, ki počenjajo te gnusobe? Bi se li ne srdil nad nami, dokler nas ne bo konec, da ne ostane nikogar in se nihče ne reši?',
        15: 'O Gospod, Bog Izraelov, ti si pravičen; kajti preostali smo kot rešenci, kakor se danes vidi. Glej, pred teboj smo v krivdi svoji, kajti nihče ne more stati pred teboj zaradi tega.',
    },
    10: {
        1: 'In ko je Ezra molil in pripoznaval jokaje in sklonjen na tleh pred hišo Božjo, se je zbrala k njemu iz Izraela silno velika množica mož in žen in otrok. Kajti ljudstvo je grozno jokalo.',
        2: 'In Sekanija, sin Jehielov, iz sinov Elamovih, izpregovori in reče Ezru: Nezvesto smo ravnali proti svojemu Bogu, ker smo si jemali žene tujke iz ljudstev dežele. A zdaj je še upanje Izraelu ob tem!',
        3: 'Sedaj torej sklenimo zavezo z Bogom svojim, da izločimo vse tiste žene in te, ki so se iz njih rodili, po svetu Gospodovem in tistih, ki trepetajo ob zapovedi Boga našega; in naj se ravna po postavi!',
        4: 'Vstani, ker to je tvoj posel, in mi bodemo pri tebi, bodi srčen in izvrši to!',
        5: 'Nato vstane Ezra in zapriseže poglavarje duhovnikov, levitov in vsega Izraela, da bodo storili po tej besedi. In so prisegli.',
        6: 'In Ezra vstane izpred hiše Božje in stopi v izbo Johanana, sinu Eliasibovega. In ko pride tja, ne je kruha in ne pije vode, ker je žaloval zaradi nezvestobe tistih, ki so bili iz ujetništva.',
        7: 'In so poslali oklic po Judovem in Jeruzalemu za vse sinove ujetništva, naj se zbero v Jeruzalemu.',
        8: 'In kdor ne pride v treh dneh, po svetu poglavarjev in starejšin, naj zapade vse imetje njegovo prokletju in bodi izključen iz zbora tistih, ki so iz ujetništva.',
        9: 'Tedaj se zbero vsi možje Judovi in Benjaminovi v Jeruzalemu, v treh dneh; bilo je dvajseti dan devetega meseca. In vse ljudstvo je sedelo na široki ulici pred hišo Božjo, trepetaje zaradi te reči in od dežja.',
        10: 'Tedaj vstane Ezra duhovnik in jih ogovori: Nezvesto ste ravnali, ker ste si vzeli žene tujke, da še pomnožite krivdo Izraelovo.',
        11: 'Sedaj torej pripoznajte Gospodu, očetov svojih Bogu, in storite, kar mu ugaja, ter se ločite od ljudstev dežele in od žen tujk!',
        12: 'In ves zbor odgovori in reče z velikim glasom: Dolžni smo storiti, kakor si nam povedal!',
        13: 'Ali ljudstvo je veliko in vreme je deževno in ne moremo stati tu zunaj, tudi se ne da opraviti v enem dnevu ali v dveh, kajti mnogoterno smo prestopali v tej reči.',
        14: 'Postavijo naj se, prosimo, naši poglavarji za ves zbor, in vsi, ki bivajo v naših mestih, oženjeni z ženami tujkami, naj prihajajo, dokler ta reč traja, ob določenih časih in ž njimi starejšine vsakega dotičnega mesta in njega sodniki, dokler se od nas ne odvrne togota srda Boga našega. –',
        15: 'Samo Jonatan, sin Asahelov, in Jahzeja, sin Tikva, sta se temu ustavljala, in Mesulam in Sabetaj levit sta jima pomagala.',
        16: 'In sinovi ujetništva so storili tako. In bili so izvoljeni: Ezra, duhovnik, možje, poglavarji očetovin po svojih očetovinah, in vsi po imenu. In imeli so sejo prvi dan desetega meseca, da bi preiskali to zadevo.',
        17: 'In do prvega dne prvega meseca so končno rešili vse zadeve mož, ki so vzeli žene tujke.',
        18: 'In našli so se med sinovi duhovnikov, ki so vzeli žene tujke: od sinov Jesua, sinu Jozadakovega, in bratov njegovih: Maaseja, Eliezer, Jarib in Gedalija.',
        19: 'In dali so svoje roke, da hočejo odpustiti svoje žene, in ker so bili krivi, so darovali ovna iz črede za svojo krivdo.',
        20: 'In iz sinov Imerjevih: Hanani in Zebadija.',
        21: 'In iz sinov Harimovih: Maaseja, Elija, Semaja, Jehiel in Uzija.',
        22: 'In iz sinov Pashurjevih: Eljoenaj, Maaseja, Izmael, Netanel, Jozabad in Elasa.',
        23: 'In iz levitov: Jozabad, Simej, Kelaja (ta je Kelita), Petahija, Juda in Eliezer.',
        24: 'In iz pevcev: Eliasib; iz vratarjev: Salum, Telem in Uri.',
        25: 'In iz Izraela: iz sinov Paroševih: Ramija, Izija, Malkija, Mijamin, Eleazar, Malkija in Benaja.',
        26: 'In iz sinov Elamovih: Matanija, Zeharija, Jehiel, Abdi, Jeremot in Elija.',
        27: 'In iz sinov Zatujevih: Eljoenaj, Eliasib, Matanija, Jeremot, Zabat in Aziza.',
        28: 'In iz sinov Bebajevih: Johanan, Hananija, Zabaj, Atlaj.',
        29: 'In iz sinov Banijevih: Mesulam, Maluk, Adaja, Jasub, Seal, Jeremot.',
        30: 'In iz sinov Pahat-moaba: Adna, Kelal, Benaja, Maaseja, Matanija, Bezalel, Binuj in Manase.',
        31: 'In iz sinov Harimovih: Eliezer, Išija, Malkija, Semaja, Simeon,',
        32: 'Benjamin, Maluk, Semarija.',
        33: 'Iz sinov Hasumovih: Matenaj, Matata, Zabad, Elifelet, Jeremaj, Manase, Simej.',
        34: 'Iz sinov Banijevih: Maadaj, Amram in Uel,',
        35: 'Benaja, Bedeja, Keluhi,',
        36: 'Vanija, Meremot, Eliasib,',
        37: 'Matanija, Matenaj in Jaasaj,',
        38: 'Bani in Binuj, Simej,',
        39: 'Selemija, Natan, Adaja,',
        40: 'Maknadebaj, Sasaj, Saraj,',
        41: 'Azarel, Selemija, Semarija,',
        42: 'Salum, Amarija, Jožef.',
        43: 'Iz sinov Nebovih: Jegiel, Matitija, Zabad, Zebina, Jadaj in Joel, Benaja.',
        44: 'Vsi ti so vzeli žene tujke in nekatere tistih žen so že rodile otroke.',
    },
}
